pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 value, uint256 warpTime, uint256 blockNum) public {
        vm.assume(value == 10 ether);
        vm.assume(warpTime > 0);
        vm.warp(warpTime);
        vm.roll(blockNum);
        vm.deal(address(this), value);
        (bool ok,) = address(c).call{value: value}("");
        assertTrue(c.pastBlockTime() <= block.timestamp);
    }
}
